wp_set_current_user(1);$tests=0;$failures=0;$prior=get_option('eipsi_native_runtime_enabled',null);$priorCron=_get_cron_array();$owner=new Owner();$d=json_decode(file_get_contents(__DIR__.'/assessment-editor/functional-fixture.json'),true);$d['id']='AE_HTTP_'.bin2hex(random_bytes(10));$d['flow']['pages']=array();$d['elements']=array($d['elements'][0]);$d['flow']['metadata_profile']='basic';$d=D::validate($d);R::save($d,0);$v=$owner->publish($d['id'],1);$assigned=$owner->assign($v['version_id'],array('kind'=>'WORDPRESS_USER','user_id'=>1));$id=$assigned['execution_id'];$token=WP_Session_Tokens::get_instance(1)->create(time()+3600);$cookie=new WP_Http_Cookie(array('name'=>LOGGED_IN_COOKIE,'value'=>wp_generate_auth_cookie(1,time()+3600,'logged_in',$token)));$frame=null;$extra=array();
function nh_assert($v,$m='Assertion failed'){if(!$v)throw new RuntimeException($m);}function nh_test($n,$fn){global $tests,$failures;$tests++;try{$fn();echo "PASS $n\n";}catch(Throwable $e){$failures++;echo "FAIL $n: ".$e->getMessage()."\n";}}
function nh_http($path,$cookies=array(),$body=null,$headers=array()){$args=array('timeout'=>15,'redirection'=>0,'cookies'=>$cookies,'headers'=>array_merge(array('Host'=>'127.0.0.1:18080'),$headers));if($body!==null){$args['method']='POST';$args['body']=$body;}$r=wp_remote_request('http://127.0.0.1'.$path,$args);nh_assert(!is_wp_error($r),is_wp_error($r)?$r->get_error_message():'HTTP failed');return array('status'=>wp_remote_retrieve_response_code($r),'body'=>wp_remote_retrieve_body($r),'headers'=>wp_remote_retrieve_headers($r));}
function nh_ajax($id,$payload,$cookies,$headers=array()){return nh_http('/wp-admin/admin-ajax.php',$cookies,array('action'=>'eipsi_native_participant','execution'=>$id,'payload'=>wp_json_encode($payload)),$headers);}
try{
nh_test('Actual native participant route denies URL-only anonymous GET',function()use($id){$r=nh_http('/?eipsi_native='.$id);nh_assert($r['status']===303&&strpos($r['headers']['location'],'eipsi_native=')!==false&&strpos($r['headers']['location'],$id)===false);});
nh_test('Actual native participant route uses authenticated assigned WordPress session',function()use($id,$cookie,&$frame){$r=nh_http('/?eipsi_native='.$id,array($cookie));nh_assert($r['status']===200,substr($r['body'],0,300));nh_assert(preg_match('/window\.eipsiNativeParticipant=(.*?);<\/script>/s',$r['body'],$m)===1);$frame=json_decode($m[1],true)['frame'];nh_assert($frame['execution_id']===$id);});
nh_test('Participant HTML mounts actual native widget artifact with cache and referrer protection',function()use($id,$cookie){$r=nh_http('/?eipsi_native='.$id,array($cookie));nh_assert(strpos($r['body'],'eipsi-public-page')!==false&&strpos($r['body'],'/themes/')===false&&strpos($r['body'],'wpadminbar')===false);nh_assert(strpos($r['body'],'assessment-participant.js')!==false&&strpos($r['body'],'eipsi-native-participant')!==false);nh_assert(strpos($r['headers']['cache-control']??'','no-cache')!==false&&($r['headers']['referrer-policy']??'')==='no-referrer');});
nh_test('Actual participant AJAX view denies anonymous ownership',function()use($id){nh_assert(nh_ajax($id,array('action'=>'view'),array())['status']===403);});
nh_test('Actual participant AJAX view accepts existing owner cookie',function()use($id,$cookie){$r=nh_ajax($id,array('action'=>'view'),array($cookie));nh_assert($r['status']===200&&json_decode($r['body'],true)['data']['execution_id']===$id);});
nh_test('Participant transport rejects cross-origin AJAX even with valid cookie',function()use($id,$cookie){nh_assert(nh_ajax($id,array('action'=>'view'),array($cookie),array('Origin'=>'https://external.invalid'))['status']===403);});
nh_test('Participant transport rejects malformed payload and unknown operation',function()use($id,$cookie){nh_assert(nh_ajax($id,array('action'=>'unknown'),array($cookie))['status']===400);});
nh_test('Actual participant save requires per-session CSRF',function()use($id,$cookie,&$frame){$m=array('contract'=>'NATIVE_PROCESS_V1','assessment_id'=>$frame['definition']['id'],'definition_ref'=>array(),'started_at'=>1000,'completed_at'=>null,'duration'=>0,'status'=>'active','recovery_used'=>false,'recovery_count'=>0,'pages'=>array(),'items'=>array(),'events'=>array(),'dropped_events'=>0);$q=array('action'=>'partial','command_id'=>'NC_HTTP_INVALID','revision'=>$frame['revision'],'version_id'=>$frame['version_id'],'csrf'=>'invalid','answers'=>array(),'touched'=>array(),'metadata'=>$m);nh_assert(nh_ajax($id,$q,array($cookie))['status']===403);});
nh_test('Actual native AJAX persists partial and resumes immutable snapshot',function()use($id,$cookie,&$frame){$key=$frame['definition']['elements'][0]['response_key'];$m=array('contract'=>'NATIVE_PROCESS_V1','assessment_id'=>$frame['definition']['id'],'definition_ref'=>array(),'started_at'=>1000,'completed_at'=>null,'duration'=>0,'status'=>'active','recovery_used'=>false,'recovery_count'=>0,'pages'=>array(),'items'=>array(),'events'=>array(),'dropped_events'=>0);$q=array('action'=>'partial','command_id'=>'NC_HTTP_SAVE','revision'=>$frame['revision'],'version_id'=>$frame['version_id'],'csrf'=>$frame['csrf'],'answers'=>array($key=>'Real HTTP response 50%'),'touched'=>array(),'metadata'=>$m);$r=nh_ajax($id,$q,array($cookie));nh_assert($r['status']===200,$r['body']);$frame=json_decode($r['body'],true)['data'];nh_assert($frame['partial']['answers'][$key]==='Real HTTP response 50%');$r=nh_http('/?eipsi_native='.$id,array($cookie));nh_assert(strpos($r['body'],'Real HTTP response 50%')!==false);});
nh_test('Actual final HTTP submission completes and clears recovery',function()use($id,$cookie,&$frame){$q=array('action'=>'submit','command_id'=>'NC_HTTP_FINAL','revision'=>$frame['revision'],'version_id'=>$frame['version_id'],'csrf'=>$frame['csrf'],'answers'=>$frame['partial']['answers'],'touched'=>array(),'metadata'=>$frame['metadata']);$r=nh_ajax($id,$q,array($cookie));nh_assert($r['status']===200,$r['body']);$frame=json_decode($r['body'],true)['data'];nh_assert($frame['state']==='COMPLETED'&&$frame['partial']===null);});
nh_test('Real persisted HTTP final is exposed through authorized analytical export',function()use($owner,$id){$x=$owner->export($id);nh_assert($x['rows'][0]['variable_name']==='ansiedad'&&$x['rows'][0]['value']==='Real HTTP response 50%');});
function nh_session($enabled){global $owner,$cookie,$extra; $d=json_decode(file_get_contents(__DIR__.'/assessment-editor/functional-fixture.json'),true);$d['id']='AE_HTTP_SESSION_'.bin2hex(random_bytes(8));$d['elements']=array($d['elements'][0]);$d['flow']['pages']=array();$d['flow']['metadata_profile']='basic';$d['flow']['save_continue']['enabled']=$enabled;$d=D::validate($d);R::save($d,0);$v=$owner->publish($d['id'],1);$a=$owner->assign($v['version_id'],array('kind'=>'WORDPRESS_USER','user_id'=>1));$extra[]=array('draft'=>$d['id'],'version'=>$v['version_id'],'id'=>$a['execution_id']);$r=nh_http('/?eipsi_native='.$a['execution_id'],array($cookie));nh_assert(preg_match('/window\.eipsiNativeParticipant=(.*?);<\/script>/s',$r['body'],$m)===1);return json_decode($m[1],true)['frame'];}
function nh_session_save($f){global $cookie;$key=$f['definition']['elements'][0]['response_key'];$m=array('contract'=>'NATIVE_PROCESS_V1','assessment_id'=>$f['definition']['id'],'definition_ref'=>array(),'started_at'=>1000,'completed_at'=>null,'duration'=>0,'status'=>'suspended','recovery_used'=>false,'recovery_count'=>0,'pages'=>array(),'items'=>array(),'events'=>array(),'dropped_events'=>0);$q=array('action'=>'partial','command_id'=>'NC_'.bin2hex(random_bytes(8)),'revision'=>$f['revision'],'version_id'=>$f['version_id'],'csrf'=>$f['csrf'],'answers'=>array($key=>'HTTP session response'),'touched'=>array(),'metadata'=>$m);$r=nh_ajax($f['execution_id'],$q,array($cookie));nh_assert($r['status']===200,$r['body']);return json_decode($r['body'],true)['data'];}
function nh_force_expire($f){global $owner;$owner->store->update('executions',array('expires_at'=>time()-1),$owner->store->prepare('id=%s',$f['execution_id']));}
nh_test('Actual HTTP session persists and returns with partial saving OFF',function()use($cookie){$f=nh_session_save(nh_session(false));$r=nh_ajax($f['execution_id'],array('action'=>'view'),array($cookie));$body=json_decode($r['body'],true)['data'];nh_assert($r['status']===200&&array_values($body['session']['answers'])[0]==='HTTP session response');nh_force_expire($f);$r=nh_ajax($f['execution_id'],array('action'=>'view'),array($cookie));$body=json_decode($r['body'],true)['data'];nh_assert($body['session_reset']&&$body['session']===null&&!$body['previous_partial_saved']);});
nh_test('Actual HTTP expired session starts blank with saved-partial notice flag',function()use($cookie,$owner){$f=nh_session_save(nh_session(true));nh_force_expire($f);$r=nh_ajax($f['execution_id'],array('action'=>'view'),array($cookie));$body=json_decode($r['body'],true)['data'];nh_assert($r['status']===200&&$body['session_reset']&&$body['session']===null&&$body['previous_partial_saved']);$x=$owner->export($f['execution_id']);nh_assert($x['rows'][0]['response_status']==='PARTIAL_SAVED'&&$x['rows'][0]['value']==='HTTP session response');});
nh_test('Actual HTTP late session mutation returns reset without accepting stale final',function()use($cookie,$owner){$f=nh_session_save(nh_session(true));nh_force_expire($f);$q=array('action'=>'submit','command_id'=>'NC_'.bin2hex(random_bytes(8)),'revision'=>$f['revision'],'version_id'=>$f['version_id'],'csrf'=>$f['csrf'],'answers'=>$f['session']['answers'],'touched'=>array(),'metadata'=>$f['metadata']);$r=nh_ajax($f['execution_id'],$q,array($cookie));$body=json_decode($r['body'],true)['data'];nh_assert($r['status']===200&&$body['session_reset']&&$body['state']==='SESSION_EXPIRED');nh_assert(count($owner->export($f['execution_id'])['saved_partials'])===1);});
nh_test('Actual HTTP archived partial cannot become an executable participant session',function()use($cookie,$owner){$f=nh_session_save(nh_session(true));nh_force_expire($f);$owner->view($f['execution_id']);$archive=$owner->export($f['execution_id'])['saved_partials'][0]['id'];nh_assert(nh_http('/?eipsi_native='.$archive,array($cookie))['status']===303);});
